<!doctype html>
<html lang="en"><head><meta charset="utf-8"><style>
@page { margin: 72px 42px 52px; } * { box-sizing: border-box; } body { margin: 0; color: #1c3027; font-family: DejaVu Sans, sans-serif; font-size: 10px; line-height: 1.5; }
