.facts { width: 100%; margin-bottom: 18px; border-collapse: collapse; } .facts td { width: 25%; padding: 9px 10px; border: 1px solid #e0e9e4; vertical-align: top; } .facts small { display: block; margin-bottom: 3px; color: #7b8982; font-size: 7px; text-transform: uppercase; } .facts strong { font-size: 9px; }
h2 { margin: 17px 0 8px; color: #1d392d; font-size: 13px; } .section { margin-bottom: 9px; padding: 11px 13px; border-left: 3px solid #6f48d8; background: #faf8ff; page-break-inside: avoid; } .section h3 { margin: 0 0 5px; color: #44268c; font-size: 10px; } .section p { margin: 0; white-space: pre-line; }
