@if(count($document['timeline']))<h2>Activity timeline</h2><table class="timeline">@foreach($document['timeline'] as $event)<tr><td class="date">{{ $event['date'] }}</td><td><strong>{{ $event['title'] }}</strong>{{ $event['description'] }}<br><small>{{ $event['actor'] }}</small></td></tr>@endforeach</table>@endif
@if(count($document['photos'] ?? []))<h2>Photographic evidence</h2><div class="photos">@foreach($document['photos'] as $photo)<div class="photo"><img src="{{ $photo['data'] }}"><strong>{{ $photo['phase'] }}</strong><span>{{ $photo['caption'] }}</span></div>@endforeach</div>@endif
